    route: 'buscar_cliente',
    cliente_nome: nome,
    output: '',
  }}];
}

if (state === 'aguardando_escolha_cliente_nova_os') {
  const lista = String(resolver.lista_texto_salva || '').trim();
  if (msg.includes('me de a lista') || msg.includes('manda a lista')) {
