function normalize(v) {
  return String(v || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
}
function cleanupName(name) {
  let out = String(name || '').trim();
  out = out.replace(/^[\s:\-]+/, '');
  out = out.replace(/^(?:e|é)\s+/i, '');
  return out.trim();
}
function extractName(msg) {
  const raw = String(msg || '').trim();
  const patterns = [
    /(?:nome do cliente\s+e|nome do cliente|cliente|abrir os para|nova os para|abrir uma nova os com o nome do cliente|abrir uma nova os com nome do cliente)\s*[:\-]?\s*(.+)$/i,
    /(?:quero abrir uma nova os com o nome do cliente|quero abrir uma nova os com nome do cliente)\s+(.+)$/i,
  ];
  for (const re of patterns) {
    const m = raw.match(re);
    if (m && m[1]) return cleanupName(m[1]);
  }
  return cleanupName(raw);
}
function parseState(value) {
  if (!value) return null;
  if (Array.isArray(value)) value = value[0];
  if (!value) return null;
  if (typeof value === 'object') return value;
  try { return JSON.parse(String(value)); } catch { return null; }
}
function openIntentWithoutName(text) {
  const t = normalize(text);
  if (!t) return false;
  const hasOpen = [
    'abrir nova os', 'abrir uma nova os', 'abrir uma nova', 'nova os', 'abrir outra os',
    'vamos abrir uma os', 'vamos abrir uma od', 'quero abrir uma ordem', 'abrir ordem',
    'nova ordem', 'e uma nova ordem', 'nao quero atualizar, quero abrir uma os'
  ].some((p) => t.includes(p));
  if (!hasOpen) return false;
  if (t.includes('nome do cliente') || t.includes('cliente ')) return false;
  return true;
}
function isSelection(text) {
  const t = normalize(text);
  return /^(\d+)$/.test(t) || /^(opcao|opção|a|e a|isso opção|pode ser a)\s*\d+$/.test(t) || /^(e essa|essa mesmo|essa)$/.test(t);
}
function selectionNumber(text) {
  const m = String(text || '').match(/(\d+)/);
  return m ? String(Number(m[1])) : '';
}
function isListRequest(text) {
  const t = normalize(text);
  return t.includes('me de a lista') || t.includes('me dê a lista') || t.includes('manda a lista');
}

const info = (() => { try { return $('setarInfo').first().json || {}; } catch (e) { return {}; } })();
const rawMsg = String(info.msgLead || '').trim();
const tecnicoId = String((() => { try { return $('BuscarTecnico').first().json.tecnico_id || $('setarInfo4').first().json.msg.identicacaoLead || ''; } catch (e) { return ''; } })()).trim();
const stateKey = 'piccinin_os:vanda_estado:' + tecnicoId;
const stateRaw = (() => { try { return $('Get Estado Nova OS').first().json?.state || []; } catch (e) { return []; } })();
let state = parseState(stateRaw);
if (state?.criado_em) {
  const age = Date.now() - new Date(state.criado_em).getTime();
  if (!Number.isFinite(age) || age > 10 * 60 * 1000) state = null;
}

const out = {
  original_msg: rawMsg,
  state_key: stateKey,
  estado_conversa: state?.estado || '',
  cliente_nome_forcado: '',
  cliente_id_forcado: '',
  opcao_cliente_forcada: '',
  option_map_salvo: '',
  lista_texto_salva: '',
  salvar_estado: false,
