  out.msgLead_final = 'Perfeito, vamos abrir uma nova OS. Informe o nome do cliente.';
} else if (state?.estado === 'aguardando_escolha_cliente_nova_os') {
  out.msgLead_final = 'SISTEMA: Use a lista salva para continuar a escolha do cliente.';
}

