function normalize(v) {
  return String(v || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
}
function cleanupName(name) {
  let out = String(name || '').trim();
  out = out.replace(/^[\s:\-]+/, '');
  out = out.replace(/^(?:e|é)\s+/i, '');
  return out.trim();
}
function extractName(msg) {
  const raw = String(msg || '').trim();
  const patterns = [
    /(?:nome do cliente\s+e|nome do cliente|cliente|abrir os para|nova os para|abrir uma nova os com o nome do cliente|abrir uma nova os com nome do cliente)\s*[:\-]?\s*(.+)$/i,
    /(?:quero abrir uma nova os com o nome do cliente|quero abrir uma nova os com nome do cliente)\s+(.+)$/i,
  ];
  for (const re of patterns) {
    const m = raw.match(re);
    if (m && m[1]) return cleanupName(m[1]);
  }
  return cleanupName(raw);
}
function parseState(value) {
  if (!value) return null;
  if (Array.isArray(value)) value = value[0];
  if (!value) return null;
  if (typeof value === 'object') return value;
  try { return JSON.parse(String(value)); } catch { return null; }
}
function openIntentWithoutName(text) {
  const t = normalize(text);
  if (!t) return false;
  const hasOpen = [
    'abrir nova os', 'abrir uma nova os', 'abrir uma nova', 'nova os', 'abrir outra os',
    'vamos abrir uma os', 'vamos abrir uma od', 'quero abrir uma ordem', 'abrir ordem',
    'nova ordem', 'e uma nova ordem', 'nao quero atualizar, quero abrir uma os'
  ].some((p) => t.includes(p));
  if (!hasOpen) return false;
  if (t.includes('nome do cliente') || t.includes('cliente ')) return false;
  return true;
}
function isSelection(text) {
  const t = normalize(text);
  return /^(\d+)$/.test(t) || /^(opcao|opção|a|e a|isso opção|pode ser a)\s*\d+$/.test(t) || /^(e essa|essa mesmo|essa)$/.test(t);
}
function selectionNumber(text) {
  const m = String(text || '').match(/(\d+)/);
  return m ? String(Number(m[1])) : '';
}
function isListRequest(text) {
  const t = normalize(text);
  return t.includes('me de a lista') || t.includes('me dê a lista') || t.includes('manda a lista');
}

const info = (() => { try { return $('setarInfo').first().json || {}; } catch (e) { return {}; } })();
const rawMsg = String(info.msgLead || '').trim();
const tecnicoId = String((() => { try { return $('BuscarTecnico').first().json.tecnico_id || $('setarInfo4').first().json.msg.identicacaoLead || ''; } catch (e) { return ''; } })()).trim();
const stateKey = 'piccinin_os:vanda_estado:' + tecnicoId;
const stateRaw = (() => { try { return $('Get Estado Nova OS').first().json?.state || []; } catch (e) { return []; } })();
let state = parseState(stateRaw);
if (state?.criado_em) {
  const age = Date.now() - new Date(state.criado_em).getTime();
  if (!Number.isFinite(age) || age > 10 * 60 * 1000) state = null;
}

const out = {
  original_msg: rawMsg,
  state_key: stateKey,
  estado_conversa: state?.estado || '',
  cliente_nome_forcado: '',
  cliente_id_forcado: '',
  opcao_cliente_forcada: '',
  option_map_salvo: '',
  lista_texto_salva: '',
  salvar_estado: false,
  estado_para_salvar: null,
  msgLead_final: rawMsg,
};

if (state?.estado === 'aguardando_nome_cliente_nova_os') {
  const nome = extractName(rawMsg);
  out.estado_conversa = state.estado;
  out.cliente_nome_forcado = nome;
  out.msgLead_final = 'SISTEMA: O tecnico esta abrindo uma nova OS. A mensagem atual e o nome do cliente: ' + nome + '. Chame buscarCliente com nome=' + nome + '.';
} else if (state?.estado === 'aguardando_escolha_cliente_nova_os') {
  const optionMap = state.option_map || {};
  const listaTexto = String(state.lista_texto || '');
  out.estado_conversa = state.estado;
  out.option_map_salvo = JSON.stringify(optionMap);
  out.lista_texto_salva = listaTexto;
  if (isListRequest(rawMsg)) {
    out.msgLead_final = 'SISTEMA: O tecnico pediu a lista salva. Repita exatamente o texto abaixo:\n' + listaTexto;
  } else if (isSelection(rawMsg)) {
    const num = selectionNumber(rawMsg);
    const chosen = optionMap[num];
    if (chosen) {
      out.opcao_cliente_forcada = num;
      out.cliente_id_forcado = String(chosen.id || '');
      out.cliente_nome_forcado = String(chosen.nome || '');
      out.msgLead_final = 'SISTEMA: O tecnico escolheu a opcao ' + num + ' da lista anterior. Use o option_map salvo para criar a OS com cliente_id=' + out.cliente_id_forcado + ' e cliente_nome=' + out.cliente_nome_forcado + '. Nao chame buscarCliente novamente.';
    } else {
      out.msgLead_final = 'SISTEMA: Ha uma lista pendente, mas a opcao informada nao bate com o option_map salvo. Use a lista salva abaixo e peca novamente a opcao correta:\n' + listaTexto;
    }
  } else {
    out.msgLead_final = 'SISTEMA: Ha uma lista pendente de escolha do cliente. Use o option_map salvo and aguarde a opcao do tecnico.';
  }
} else if (openIntentWithoutName(rawMsg)) {
  out.estado_conversa = 'aguardando_nome_cliente_nova_os';
  out.salvar_estado = true;
  out.estado_para_salvar = {
    estado: 'aguardando_nome_cliente_nova_os',
    cliente_nome_pesquisado: '',
    option_map: {},
    lista_texto: '',
    id_conversa: String(info.id_conversa || ''),
    criado_em: new Date().toISOString(),
  };
  out.msgLead_final = 'Perfeito, vamos abrir uma nova OS. Informe o nome do cliente.';
} else if (state?.estado === 'aguardando_escolha_cliente_nova_os') {
  out.msgLead_final = 'SISTEMA: Use a lista salva para continuar a escolha do cliente.';
}

